const manifest = {
  pins: { springAi: true, boot: true, java: true },
  chat: { bean: true, streaming: true },
  advisors: ['memory', 'rag', 'logging'],
  tools: ['lookup', 'refund@gated'],
  rag: { followups: true },
  eval: { gold: 12 },
};
const checks = [
  ['versions pinned', manifest.pins.springAi && manifest.pins.boot],
  ['advisor order', manifest.advisors.indexOf('memory') < manifest.advisors.indexOf('rag')],
  ['money gated', manifest.tools.some((t) => t.endsWith('@gated'))],
  ['followups proven', manifest.rag.followups === true],
  ['eval sized', manifest.eval.gold >= 10],
];
for (const [label, ok] of checks) console.log((ok ? 'PASS ' : 'FAIL ') + label);
console.log(checks.every(([, ok]) => ok) ? 'manifest sound' : 'manifest BROKEN');

